-- Actual enrichment inputs have independent monotonic versions. Generated
-- summaries and question metadata do not change these input versions.
CREATE TABLE knowledge_enrichment_row_versions (
 row_kind TEXT NOT NULL CHECK(row_kind IN ('knowledge','chunk','model','routing','tenant')),
 row_id TEXT NOT NULL CHECK(length(trim(row_id)) > 0),
 revision BIGINT NOT NULL CHECK(revision > 0), PRIMARY KEY(row_kind,row_id)
);
CREATE TABLE knowledge_producer_inputs (
 id TEXT PRIMARY KEY CHECK(length(trim(id)) > 0),
 admission_id TEXT NOT NULL REFERENCES knowledge_input_admissions(admission_id),
 purpose TEXT NOT NULL CHECK(purpose IN ('summary','question','image')),
 input_digest TEXT NOT NULL CHECK(length(input_digest) = 64),
 original_proof TEXT NOT NULL,
 actor_selector TEXT NOT NULL,
 model_digest TEXT NOT NULL CHECK(length(model_digest) = 64)
);
CREATE FUNCTION knowledge_producer_input_immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'immutable actual producer input'; END; $$;
CREATE TRIGGER knowledge_producer_input_immutable BEFORE UPDATE OR DELETE ON knowledge_producer_inputs FOR EACH ROW EXECUTE FUNCTION knowledge_producer_input_immutable();
INSERT INTO knowledge_enrichment_row_versions(row_kind,row_id,revision) SELECT 'knowledge',id,1 FROM knowledges;
CREATE FUNCTION knowledge_enrichment_knowledge_version() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP = 'UPDATE' AND NOT (OLD.tenant_id IS DISTINCT FROM NEW.tenant_id OR OLD.knowledge_base_id IS DISTINCT FROM NEW.knowledge_base_id OR OLD.type IS DISTINCT FROM NEW.type OR OLD.title IS DISTINCT FROM NEW.title OR OLD.source IS DISTINCT FROM NEW.source OR OLD.channel IS DISTINCT FROM NEW.channel OR OLD.file_name IS DISTINCT FROM NEW.file_name OR OLD.folder_path IS DISTINCT FROM NEW.folder_path OR OLD.file_type IS DISTINCT FROM NEW.file_type OR OLD.file_hash IS DISTINCT FROM NEW.file_hash OR OLD.file_path IS DISTINCT FROM NEW.file_path OR OLD.custom_metadata::jsonb IS DISTINCT FROM NEW.custom_metadata::jsonb OR OLD.deleted_at IS DISTINCT FROM NEW.deleted_at OR (CASE WHEN OLD.channel = 'nextcloud' AND NEW.channel = 'nextcloud' THEN OLD.metadata::jsonb - 'nextcloud_etag' IS DISTINCT FROM NEW.metadata::jsonb - 'nextcloud_etag' ELSE OLD.metadata::jsonb IS DISTINCT FROM NEW.metadata::jsonb END)) THEN RETURN NEW; END IF; INSERT INTO knowledge_enrichment_row_versions(row_kind,row_id,revision) VALUES('knowledge',CASE WHEN TG_OP = 'DELETE' THEN OLD.id ELSE NEW.id END,1) ON CONFLICT(row_kind,row_id) DO UPDATE SET revision=knowledge_enrichment_row_versions.revision+1; IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END; $$;
CREATE TRIGGER knowledge_enrichment_knowledge_version AFTER INSERT OR UPDATE OR DELETE ON knowledges FOR EACH ROW EXECUTE FUNCTION knowledge_enrichment_knowledge_version();
INSERT INTO knowledge_enrichment_row_versions(row_kind,row_id,revision) SELECT 'chunk',id,1 FROM chunks;
CREATE FUNCTION knowledge_enrichment_chunk_version() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP = 'UPDATE' AND NOT (OLD.tenant_id IS DISTINCT FROM NEW.tenant_id OR OLD.knowledge_base_id IS DISTINCT FROM NEW.knowledge_base_id OR OLD.knowledge_id IS DISTINCT FROM NEW.knowledge_id OR OLD.content IS DISTINCT FROM NEW.content OR OLD.source_content IS DISTINCT FROM NEW.source_content OR OLD.context_header IS DISTINCT FROM NEW.context_header OR OLD.chunk_type IS DISTINCT FROM NEW.chunk_type OR OLD.image_info IS DISTINCT FROM NEW.image_info OR OLD.parent_chunk_id IS DISTINCT FROM NEW.parent_chunk_id OR OLD.pre_chunk_id IS DISTINCT FROM NEW.pre_chunk_id OR OLD.next_chunk_id IS DISTINCT FROM NEW.next_chunk_id OR OLD.start_at IS DISTINCT FROM NEW.start_at OR OLD.end_at IS DISTINCT FROM NEW.end_at OR OLD.chunk_index IS DISTINCT FROM NEW.chunk_index OR OLD.content_revision IS DISTINCT FROM NEW.content_revision OR OLD.is_enabled IS DISTINCT FROM NEW.is_enabled OR OLD.deleted_at IS DISTINCT FROM NEW.deleted_at) THEN RETURN NEW; END IF; INSERT INTO knowledge_enrichment_row_versions(row_kind,row_id,revision) VALUES('chunk',CASE WHEN TG_OP = 'DELETE' THEN OLD.id ELSE NEW.id END,1) ON CONFLICT(row_kind,row_id) DO UPDATE SET revision=knowledge_enrichment_row_versions.revision+1; IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END; $$;
CREATE TRIGGER knowledge_enrichment_chunk_version AFTER INSERT OR UPDATE OR DELETE ON chunks FOR EACH ROW EXECUTE FUNCTION knowledge_enrichment_chunk_version();
INSERT INTO knowledge_enrichment_row_versions(row_kind,row_id,revision) SELECT 'model',id,1 FROM models;
CREATE FUNCTION knowledge_enrichment_model_version() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP = 'UPDATE' AND NOT (to_jsonb(OLD) IS DISTINCT FROM to_jsonb(NEW)) THEN RETURN NEW; END IF; INSERT INTO knowledge_enrichment_row_versions(row_kind,row_id,revision) VALUES('model',CASE WHEN TG_OP = 'DELETE' THEN OLD.id ELSE NEW.id END,1) ON CONFLICT(row_kind,row_id) DO UPDATE SET revision=knowledge_enrichment_row_versions.revision+1; IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END; $$;
CREATE TRIGGER knowledge_enrichment_model_version AFTER INSERT OR UPDATE OR DELETE ON models FOR EACH ROW EXECUTE FUNCTION knowledge_enrichment_model_version();
INSERT INTO knowledge_enrichment_row_versions(row_kind,row_id,revision) SELECT 'routing',CAST(id AS TEXT),1 FROM knowledge_bases;
CREATE FUNCTION knowledge_enrichment_routing_version() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP = 'UPDATE' AND NOT (OLD.tenant_id IS DISTINCT FROM NEW.tenant_id OR OLD.vector_store_id IS DISTINCT FROM NEW.vector_store_id OR OLD.storage_backend_id IS DISTINCT FROM NEW.storage_backend_id OR OLD.storage_provider_config::jsonb IS DISTINCT FROM NEW.storage_provider_config::jsonb OR OLD.cos_config::jsonb IS DISTINCT FROM NEW.cos_config::jsonb OR OLD.deleted_at IS DISTINCT FROM NEW.deleted_at) THEN RETURN NEW; END IF; INSERT INTO knowledge_enrichment_row_versions(row_kind,row_id,revision) VALUES('routing',CAST(CASE WHEN TG_OP = 'DELETE' THEN OLD.id ELSE NEW.id END AS TEXT),1) ON CONFLICT(row_kind,row_id) DO UPDATE SET revision=knowledge_enrichment_row_versions.revision+1; IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END; $$;
CREATE TRIGGER knowledge_enrichment_routing_version AFTER INSERT OR UPDATE OR DELETE ON knowledge_bases FOR EACH ROW EXECUTE FUNCTION knowledge_enrichment_routing_version();
INSERT INTO knowledge_enrichment_row_versions(row_kind,row_id,revision) SELECT 'tenant',CAST(id AS TEXT),1 FROM tenants;
CREATE FUNCTION knowledge_enrichment_tenant_version() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP = 'UPDATE' AND NOT (OLD.status IS DISTINCT FROM NEW.status OR OLD.retriever_engines::jsonb IS DISTINCT FROM NEW.retriever_engines::jsonb OR OLD.credentials::jsonb IS DISTINCT FROM NEW.credentials::jsonb OR OLD.storage_engine_config::jsonb IS DISTINCT FROM NEW.storage_engine_config::jsonb OR OLD.default_storage_backend_id IS DISTINCT FROM NEW.default_storage_backend_id OR OLD.deleted_at IS DISTINCT FROM NEW.deleted_at) THEN RETURN NEW; END IF; INSERT INTO knowledge_enrichment_row_versions(row_kind,row_id,revision) VALUES('tenant',CAST(CASE WHEN TG_OP = 'DELETE' THEN OLD.id ELSE NEW.id END AS TEXT),1) ON CONFLICT(row_kind,row_id) DO UPDATE SET revision=knowledge_enrichment_row_versions.revision+1; IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END; $$;
CREATE TRIGGER knowledge_enrichment_tenant_version AFTER INSERT OR UPDATE OR DELETE ON tenants FOR EACH ROW EXECUTE FUNCTION knowledge_enrichment_tenant_version();
